/** Lambert asimutal flatetro (30° V, 50° N) i NA-kartets enheter. */
export function naXY(lon: number, lat: number): [number, number] {
  const r = Math.PI / 180;
  const l0 = -30 * r;
  const p0 = 50 * r;
  const l = lon * r;
  const p = lat * r;
  const k = Math.sqrt(2 / (1 + Math.sin(p0) * Math.sin(p) + Math.cos(p0) * Math.cos(p) * Math.cos(l - l0)));
  const x = k * Math.cos(p) * Math.sin(l - l0);
  const y = k * (Math.cos(p0) * Math.sin(p) - Math.sin(p0) * Math.cos(p) * Math.cos(l - l0));
  return [(x * 1000 - (-760)) * 0.631578947368421, (-y * 1000 - (-560)) * 0.631578947368421];
}
