/** Ortografisk projeksjon (35° V, 55° N), radius 200. Punkter på baksiden legges på randen. */
export function globeXY(lon: number, lat: number): [number, number] {
  const r = Math.PI / 180;
  const l0 = -35 * r;
  const p0 = 55 * r;
  const l = lon * r;
  const p = lat * r;
  let x = Math.cos(p) * Math.sin(l - l0);
  let y = Math.cos(p0) * Math.sin(p) - Math.sin(p0) * Math.cos(p) * Math.cos(l - l0);
  const c = Math.sin(p0) * Math.sin(p) + Math.cos(p0) * Math.cos(p) * Math.cos(l - l0);
  if (c < 0) {
    const n = Math.hypot(x, y) || 1;
    x /= n;
    y /= n;
  }
  return [x * 200, -y * 200];
}
